# -*- coding: utf-8 -*-
"""Lecture 44 vignette pool A -- pleura and pleurisy (s3-14), pneumothorax types and presentation (s16-25),
pneumothorax imaging and size (s26-35) and aspiration, chest tube, pleurodesis and surgery (s36-50).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md: the key names the decisive clue and the slide fact;
each wrong choice says why it fails for THIS patient, the replacing fact, and a "Tell:".

Held for the scope (cms_e7l44_scope.py): fremitus is decreased for pneumothorax (s22) as for effusion (s87), never
increased; Marfan syndrome makes a spontaneous pneumothorax secondary (s20) even in a tall, thin young man (Gray's
"classic board question", [24:02]); computed tomography is the gold standard (s33-34) and the upright film the initial
test (s26) -- "don't confuse gold standard with best initial test" [33:18]; size uses the apex-to-cupola distance
(s28), and no stem puts a pneumothorax at exactly 3 cm. Pleurodesis is keyed as the slide reads it (adhesions, s45),
never as his spoken "more fluid" or "the layers slide". No item asks the chest tube's less common 2nd/3rd space site
(s73). Catheter aspiration contraindications are s39's list; their "what instead" comes from s49, s56 and s57.
Picture slides used: s28 (apex-to-cupola vs hilum), s29 (deep sulcus), s34 (CT gold standard, stratosphere sign,
B-lines), s71 (straight line on a hemopneumothorax, distractor only), all read from the renders.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e7l44_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


def ORD(d, asc):
    d["ordered"] = True; d["asc"] = asc; return d


